    static class Dog {
        String name; int age;
        Dog(String name, int age) { this.name = name; this.age = age; }
    }
    public static void main(String[] args) {
        Dog d1 = new Dog("Rex", 3);
        Dog d2 = d1;                 // second reference to the SAME object
        Dog d3 = new Dog("Rex", 3);  // a different object with equal data
        d2.age++;                    // visible through d1 as well
        System.out.println("d1 " + d1.name + " " + d1.age);
        System.out.println("d3 " + d3.name + " " + d3.age);
