public class Main {
    static class Room { String name; Room(String n) { name = n; } }
    static class Player { String name; Player(String n) { name = n; } }
    // Composition: House creates its rooms and never hands them out.
    static class House {
        private final List<Room> rooms = new ArrayList<>();
        House() { rooms.add(new Room("Kitchen")); rooms.add(new Room("Bedroom")); }
        String describe() {
            StringBuilder sb = new StringBuilder();
            for (Room r : rooms) sb.append(sb.length() > 0 ? ", " : "").append(r.name);
            return sb.toString();
        }
    }
    // Aggregation: Team receives players that exist on their own.
    static class Team {
        final List<Player> players = new ArrayList<>();
        void add(Player p) { players.add(p); }
        void disband() { players.clear(); }
    }
    public static void main(String[] args) {
        House h = new House();
        System.out.println("House rooms: " + h.describe());
        Player ann = new Player("Ann");
        Team t = new Team();
        t.add(ann);
        System.out.println("Team has " + t.players.size() + " player");
        t.disband();                  // the team is gone, the part is not
        System.out.println("After disband, player still exists: " + ann.name);
    }
}

