public class Main {
    // Strategy: pay rules live in small objects the employee holds.
    interface PayPolicy { int pay(int hours); }
    static class Salaried implements PayPolicy {
        public int pay(int hours) { return 3000; }
    }
    static class Hourly implements PayPolicy {
        private final int rate;
        Hourly(int rate) { this.rate = rate; }
        public int pay(int hours) { return rate * hours; }
    }
    static class Employee {
        private final String name;
        private PayPolicy policy;   // composition: has-a policy, delegates to it
        Employee(String name, PayPolicy p) { this.name = name; this.policy = p; }
        void changePolicy(PayPolicy p) { policy = p; }   // swap at runtime, same object
        void printPay(int hours) { System.out.println(name + ": " + policy.pay(hours)); }
    }
    public static void main(String[] args) {
        Employee ann = new Employee("Ann", new Salaried());
        ann.printPay(160);
        ann.changePolicy(new Hourly(20));   // no SalariedToHourly subclass needed
        ann.printPay(160);
    }
}

