import java.util.*;

public class Main {
    static class Course {
        final String name;
        private final List<Student> students = new ArrayList<>();
        Course(String n) { name = n; }
        // Package-private: only Student calls these, so both sides stay in sync.
        void addInternal(Student s) { students.add(s); }
        void removeInternal(Student s) { students.remove(s); }
        String roster() { List<String> r = new ArrayList<>(); for (Student s : students) r.add(s.name); return r.toString(); }
    }
    static class Student {
        final String name;
        private final List<Course> courses = new ArrayList<>();
        Student(String n) { name = n; }
        // Single entry point: updates both sides together.
        void enroll(Course c) { courses.add(c); c.addInternal(this); }
        void drop(Course c) { courses.remove(c); c.removeInternal(this); }
        String list() { List<String> r = new ArrayList<>(); for (Course c : courses) r.add(c.name); return r.toString(); }
    }
    public static void main(String[] args) {
        Student ann = new Student("Ann"), bob = new Student("Bob");
        Course math = new Course("Math"), art = new Course("Art");
        ann.enroll(math); ann.enroll(art); bob.enroll(math);
        System.out.println("Ann courses: " + ann.list());
        System.out.println("Math students: " + math.roster());
        ann.drop(math);
        System.out.println("After Ann drops Math: " + math.roster());
    }
}

